import{_ as o,o as t,c as d,a5 as s}from"./chunks/framework.DSg0KOwT.js";const p=JSON.parse('{"title":"Per-widget list sort mode","description":"","frontmatter":{},"headers":[],"relativePath":"contributor-guide/architecture/widget-rendering/list-sort-mode.md","filePath":"contributor-guide/architecture/widget-rendering/list-sort-mode.md"}'),a={name:"contributor-guide/architecture/widget-rendering/list-sort-mode.md"};function c(r,e,i,n,g,h){return t(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="per-widget-list-sort-mode" tabindex="-1">Per-widget list sort mode <a class="header-anchor" href="#per-widget-list-sort-mode" aria-label="Permalink to &quot;Per-widget list sort mode&quot;">​</a></h1><p>How a Findings-tab widget opts into the shared list sort mode.</p><p><code>src/view/impact-sort.ts</code> (<code>canToggleSort</code>, <code>orderByImpact</code>, <code>stageIdOf</code>, <code>byStageAsc</code>), <code>src/view/useSortMode.ts</code> and <code>src/view/SortModeToggle.tsx</code> are a shared, opt-in set a Findings-tab active widget can use to let its own expanded, multi-row list default to the verdict&#39;s order instead of stage number: <code>orderByImpact</code> places each row at its best-ranked finding in the run interpretation&#39;s <code>savingsRank</code> (core&#39;s <code>rankBySavings</code>: stage task time or idle core time, then potential savings). The export bundle cannot import that ranking, so views read the carried rank. Each of the widgets below gets its <code>sortMode</code> (<code>SortMode</code>, <code>&#39;impact&#39; | &#39;stage&#39;</code>, default <code>&#39;impact&#39;</code>) from <code>useSortMode</code>, which forces impact order at Basic density, and renders a <code>SortModeToggle</code> in the <code>WidgetCard</code> <code>badges</code> slot, so it sits on the title row itself rather than floating in the body: a button alongside the widget&#39;s tag badges (a <code>WidgetCard</code> header renders <code>badges</code> beside the title heading, never inside another control). Every widget below carries the same <code>canToggleSort</code> check, which <code>useSortMode</code> binds to the interpretation: <code>Skew.tsx</code>, <code>TinyTask.tsx</code>, <code>StageShape.tsx</code>, <code>ShuffleIO.tsx</code> (narrowed to <code>shuffle</code>), <code>PartitionSizing.tsx</code>, <code>Spill.tsx</code>, <code>GcPressure.tsx</code> (both its high-GC and low-GC sections, one shared toggle), <code>RetryWaste.tsx</code>, <code>StageFailed.tsx</code>, <code>TaskFailures.tsx</code>, <code>SlowHost.tsx</code>, <code>StageSlowness.tsx</code>, <code>Straggler.tsx</code>, <code>SpeculationWaste.tsx</code>, <code>ColdStart.tsx</code> (one widget per type, each sorting only its own flat issue list), and <code>DuplicatePlanSubtree.tsx</code>/ <code>SmallFiles.tsx</code>/<code>NestedLoopJoin.tsx</code>/<code>JoinKeyCast.tsx</code>/<code>MergeRewrite.tsx</code>/<code>UnprunedScan.tsx</code>/<code>PythonUdf.tsx</code>/<code>UnderBroadcast.tsx</code>/<code>OverBroadcast.tsx</code> (each reorders its own list by <code>stageIdOf</code>, the lowest stage id its finding touches). It is a two-segment <code>ToggleGroup</code> (Impact / Stage; optional <code>stageLabel</code>, default &quot;Stage&quot;, which no caller overrides), wrapped in <code>AdvancedOnly</code>: stage number is the one axis every one of these widgets&#39; items can be compared on. Neither mode sorts by impact band, which ranks findings by how bad they are, not by how much fixing them would save. A per-stage detector&#39;s own <code>finding.stageId</code> is the sort key directly; a sql-scope finding that spans several stages (<code>duplicatePlanSubtree</code>, <code>smallFiles</code>, <code>nestedLoopJoin</code>, <code>joinKeyCast</code>, <code>mergeRewrite</code>, <code>unprunedScan</code>, <code>pythonUdf</code>, <code>underBroadcast</code>, <code>overBroadcast</code>, via <code>stageIds</code>) sorts by the lowest stage id it touches (<code>stageIdOf</code>). The toggle renders only when <code>canToggleSort</code> holds: the card is open, a finding in the rows has a place in <code>savingsRank</code>, and the stage order lists a different sequence of stage ids than the impact order. A widget passes the same rows, in the same order, that it passes to <code>orderBy</code>, with the same finding and stage accessors. The gate compares the stage id of each position in both orders over all rows, so pagination does not affect it, and rows tied on one stage never show it. The toggle is hidden when the stage order adds no stage information: all rows share one stage, have none, or are already in stage order. With no ranked finding the impact order is the input order, so the toggle would do nothing. Rows with no rankable finding, and <code>byStageAsc</code> ties, keep their prior relative order (<code>Array.prototype.sort</code>&#39;s stability) rather than being shuffled. <code>GcPressure.tsx</code> shows its one toggle when either of its two sections has differing orders. <code>FixTheseFirst</code>&#39;s own expanded group list (see &quot;Findings tab&quot; above) sorts by impact on its own and does not use this pattern; it has no stage-order toggle.</p>',3)])])}const w=o(a,[["render",c]]);export{p as __pageData,w as default};
